class Solution {
  public String fractionAddition(String expression) {
    long numerator = 0, denominator = 1;
    int i = 0;
    while (i < expression.length()) {
      int sign = 1;
      if (expression.charAt(i) == '+' || expression.charAt(i) == '-')
        sign = expression.charAt(i++) == '+' ? 1 : -1;
      int slash = expression.indexOf('/', i), end = slash + 1;
      while (end < expression.length() && Character.isDigit(expression.charAt(end))) end++;
      long num = sign * Long.parseLong(expression.substring(i, slash));
      long den = Long.parseLong(expression.substring(slash + 1, end));
      numerator = numerator * den + num * denominator;
      denominator *= den;
      long g = gcd(Math.abs(numerator), denominator);
      numerator /= g;
      denominator /= g;
      i = end;
    }
    return numerator + "/" + denominator;
  }

  private long gcd(long a, long b) {
    while (b != 0) {
      long t = a % b;
      a = b;
      b = t;
    }
    return a;
  }
}
